def transform(grid):
    out=[r[:] for r in grid]
    h=len(grid); w=len(grid[0])
    cols=[c for c in range(w) if any(grid[r][c]!=0 for r in range(h))]
    runs=[]
    for c in cols:
        if not runs or c!=runs[-1][-1]+1: runs.append([c])
        else: runs[-1].append(c)
    if len(runs)==2:
        a,b=runs
        if len(a)==len(b):
            ra=[r for r in range(h) if any(grid[r][c] for c in a)]
            rb=[r for r in range(h) if any(grid[r][c] for c in b)]
            if ra and rb:
                aa=list(range(min(ra),max(ra)+1)); bb=list(range(min(rb),max(rb)+1))
                if len(aa)==len(bb) and all(grid[r][c]!=0 for r in bb for c in b):
                    for r,s in zip(aa,bb):
                        for c,d in zip(a,b):
                            out[r][c]=grid[s][d]
                            out[s][d]=grid[r][c]
    return out

